import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

/**
 * @param {object} schema
 * @returns {string} ESM source of a standalone validator (default export)
 */
export function generateValidatorSource(schema) {
  const Ajv = require('ajv').default;
  const standaloneCode = require('ajv/dist/standalone').default;
  const ajv = new Ajv({
    allErrors: true,
    strict: true,
    code: { source: true, esm: true, lines: true },
  });
  const validate = ajv.compile(schema);
  return (
    '// GENERATED by scripts/generate-validator.mjs from mfe-manifest.schema.json. Do not edit.\n' +
    '/* eslint-disable */\n' +
    '// @ts-nocheck\n' +
    standaloneCode(ajv, validate)
  );
}
